import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.Arrays;import java.util.StringTokenizer;public class TestClass {static class Edge implements Comparable<Edge> {int u, v;long c;double logC;public Edge(int u, int v, long c) {this.u = u;this.v = v;this.c = c;this.logC = Math.log(c);}public int compareTo(Edge other) {return Double.compare(this.logC, other.logC);}}static class DSU {int[] parent;public DSU(int n) {parent = new int[n + 1];for (int i = 0; i <= n; i++) parent[i] = i;}public int find(int i) {if (parent[i] == i) return i;return parent[i] = find(parent[i]);}public boolean union(int i, int j) {int rootI = find(i);int rootJ = find(j);if (rootI != rootJ) {parent[rootI] = rootJ;return true;}return false;}}public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line = br.readLine();if (line == null) return;int T = Integer.parseInt(line.trim());while (T-- > 0) {StringTokenizer st = new StringTokenizer(br.readLine());int N = Integer.parseInt(st.nextToken());int M = Integer.parseInt(st.nextToken());Edge[] edges = new Edge[M];for (int i = 0; i < M; i++) {st = new StringTokenizer(br.readLine());int u = Integer.parseInt(st.nextToken());int v = Integer.parseInt(st.nextToken());long c = Long.parseLong(st.nextToken());edges[i] = new Edge(u, v, c);}Arrays.sort(edges);DSU dsu = new DSU(N);long result = 1;long MOD = 1000000007;int count = 0;for (int i = 0; i < M && count < N - 1; i++) {if (dsu.union(edges[i].u, edges[i].v)) {result = (result * (edges[i].c % MOD)) % MOD;count++;}}System.out.println(result);}}}